 static void ValidatePorts(string value){foreach(string part in value.Split(',')){var bounds=part.Split('-');int a,b;if(bounds.Length>2||!int.TryParse(bounds[0],out a)||a<1||a>65535)throw new Exception("Некорректный диапазон портов: "+part);if(bounds.Length==2&&(!int.TryParse(bounds[1],out b)||b<a||b>65535))throw new Exception("Некорректный диапазон портов: "+part);}}
