 public static string Normalize(string text,string filename){var result=new System.Collections.Generic.List<string>();bool ip=filename.StartsWith("ipset");foreach(string line in text.Split('\n')){string v=line.Trim();if(v==""||v.StartsWith("#")){result.Add(v);continue;}if(ip){var bits=v.Split('/');System.Net.IPAddress addr;int prefix;if(bits.Length>2||!System.Net.IPAddress.TryParse(bits[0],out addr))throw new Exception("Некорректный IP: "+v);if(bits.Length==2&&(!int.TryParse(bits[1],out prefix)||prefix<0||prefix>(addr.AddressFamily==System.Net.Sockets.AddressFamily.InterNetwork?32:128)))throw new Exception("Некорректная маска: "+v);}else{Uri uri;if(v.Contains("://")&&Uri.TryCreate(v,UriKind.Absolute,out uri))v=uri.Host;v=v.TrimEnd('.').ToLowerInvariant();v=new System.Globalization.IdnMapping().GetAscii(v);if(v.Length>253||!v.Contains(".")||v.Split('.').Any(x=>x.Length==0||x.Length>63||!Regex.IsMatch(x,@"^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$")))throw new Exception("Некорректный домен: "+v);}if(!result.Contains(v))result.Add(v);}if(!result.Any(x=>x.Length>0&&!x.StartsWith("#"))&&filename=="list-general-user.txt")result.Add("domain.example.abc");return string.Join("\r\n",result)+"\r\n";}
 void StartEngine(){
 if(engine!=null&&!engine.HasExited)throw new Exception("Выбранная стратегия уже запущена.");
 if(Process.GetProcessesByName("winws").Length>0)throw new Exception("winws уже работает. Остановите текущую стратегию или службу.");
