 string tcp="12",udp="12",mode="disabled",tr="1024-65535",ur=tr;
 string game=Path.Combine(root,"utils","game_filter.enabled");if(File.Exists(game)){mode="all";foreach(string l in File.ReadAllLines(game)){var pair=l.Split('=');if(pair.Length!=2)continue;if(pair[0]=="mode")mode=pair[1];if(pair[0]=="tcp")tr=pair[1];if(pair[0]=="udp")ur=pair[1];}}if(mode=="all"||mode=="tcp")tcp=tr;if(mode=="all"||mode=="udp")udp=ur;
 if(!Regex.IsMatch(tcp,@"^[0-9,-]+$")||!Regex.IsMatch(udp,@"^[0-9,-]+$"))throw new Exception("Некорректные порты игрового фильтра.");
 string source=File.ReadAllText(Path.Combine(root,Convert.ToString(strategies.SelectedItem)));int at=source.IndexOf("winws.exe\"",StringComparison.OrdinalIgnoreCase);if(at<0)throw new Exception("Не найден запуск winws.");string arguments=source.Substring(at+10).Replace("^\r\n"," ").Replace("^\n"," ").Replace("^!","!").Trim();arguments=arguments.Replace("%BIN%",Path.Combine(root,"bin")+"\\").Replace("%LISTS%",Path.Combine(root,"lists")+"\\").Replace("%GameFilterTCP%",tcp).Replace("%GameFilterUDP%",udp);if(Regex.IsMatch(arguments,@"%[a-zA-Z_]+%"))throw new Exception("В стратегии обнаружены неизвестные переменные.");
 var psi=new ProcessStartInfo(Path.Combine(root,"bin","winws.exe"),arguments){WorkingDirectory=Path.Combine(root,"bin"),UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};
