 void StopEngine(){var processes=Process.GetProcessesByName("winws");if(processes.Length>0&&MessageBox.Show("Остановить все процессы winws (включая запущенные отдельно)?","Остановка",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;using(var sc=new System.ServiceProcess.ServiceController("zapret")){try{if(sc.Status!=System.ServiceProcess.ServiceControllerStatus.Stopped){sc.Stop();sc.WaitForStatus(System.ServiceProcess.ServiceControllerStatus.Stopped,TimeSpan.FromSeconds(8));}}catch(InvalidOperationException){}}foreach(var p in processes){try{if(!p.HasExited)p.Kill();}finally{p.Dispose();}}status.Text="Обход остановлен";}
