 void RunTool(string label){if(tool!=null&&!tool.HasExited)throw new Exception("Завершите текущий инструмент перед запуском следующего.");tabs.SelectedIndex=1;log.Clear();string source=File.ReadAllText(Path.Combine(root,"service.bat"));if(label=="service_install"){int from=source.IndexOf("echo Pick one of the options:");int to=source.IndexOf(":: Args that should be followed by value",from);if(from<0||to<0)throw new Exception("Изменился формат service.bat");string selected=Convert.ToString(strategies.SelectedItem);source=source.Substring(0,from)+"set \"choice=1\"\r\nset \"file1="+selected+"\"\r\nset \"selectedFile="+selected+"\"\r\n"+source.Substring(to);}string marker="setlocal EnableDelayedExpansion";source=source.Replace(marker,marker+"\r\ncall :ipset_switch_status\r\ncall :game_switch_status\r\ncall :check_updates_switch_status\r\ngoto "+label);source=Regex.Replace(source,@"(?im)^goto menu\s*$","exit /b");source=Regex.Replace(source,@"(?im)^\s*pause\s*$","set /p GUI_PAUSE=Press Enter to continue: ");string path=Path.Combine(root,"service.leviafan.bat");File.WriteAllText(path,source,new UTF8Encoding(false));var psi=new ProcessStartInfo("cmd.exe","/d /c \"\""+path+"\" admin\""){WorkingDirectory=root,UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=Encoding.GetEncoding(866),StandardErrorEncoding=Encoding.GetEncoding(866)};tool=new Process{StartInfo=psi,EnableRaisingEvents=true};tool.ErrorDataReceived+=(s,e)=>{if(e.Data!=null)Append(e.Data);};tool.Exited+=(s,e)=>Append("Инструмент завершён. Проверьте вывод выше.");tool.Start();System.Threading.Tasks.Task.Factory.StartNew(()=>{byte[] buffer=new byte[1024];int n;while((n=tool.StandardOutput.BaseStream.Read(buffer,0,buffer.Length))>0)Append(Encoding.GetEncoding(866).GetString(buffer,0,n));});tool.BeginErrorReadLine();}
